1	/* A TTL cache for the JSON data files both pages download.
2	 *
3	 * The site ships no server it controls: GitHub Pages sets its own
4	 * `Cache-Control` and there is no way to vary it per file. So the freshness
5	 * policy lives here, on the client, where each file can be given the lifetime
6	 * its *content* actually has:
7	 *
8	 *   - the catalogue the planner searches turns over rarely and is the bulkiest
9	 *     blocking download, so it is held for days;
10	 *   - ticket availability changes through the festival and is held for a day;
11	 *   - descriptions are effectively immutable and are held for a week.
12	 *
13	 * Payloads go into the Cache Storage API rather than localStorage, whose ~5 MB
14	 * ceiling the catalogue alone would breach. Cache Storage has no expiry of its
15	 * own, so the clock is kept beside it as a small localStorage map of
16	 * url -> epoch ms of the last fetch.
17	 *
18	 * Pure of any page: both index.html (js/app.js) and the planner (plan/plan.js)
19	 * resolve their relative data urls against the same origin, so they share one
20	 * cache and one stamp map, and a file fetched by either is reused by the other.
21	 */
22	
23	export const DAY_MS = 24 * 60 * 60 * 1000;
24	
25	const CACHE_NAME = "edfringe-data-v1";
26	const STAMPS_KEY = "edfringe.data.fetched.v1"; // url -> epoch ms of the last fetch
27	
28	export async function fetchJson(url) {
29	  const res = await fetch(url);
30	  if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
31	  return res.json();
32	}
33	
34	/* When each cached URL was last fetched. A plain localStorage map — the
35	 * payloads live in Cache Storage, this is only the clock beside them. */
36	function fetchStamps() {
37	  try {
38	    const raw = JSON.parse(localStorage.getItem(STAMPS_KEY) || "{}");
39	    return raw && typeof raw === "object" ? raw : {};
40	  } catch {
41	    return {};
42	  }
43	}
44	
45	function stampFetch(url) {
46	  try {
47	    localStorage.setItem(STAMPS_KEY, JSON.stringify({ ...fetchStamps(), [url]: Date.now() }));
48	  } catch {
49	    /* private mode / full quota — we just re-fetch next time */
50	  }
51	}
52	
53	function unstampFetch(url) {
54	  try {
55	    const stamps = fetchStamps();
56	    delete stamps[url];
57	    localStorage.setItem(STAMPS_KEY, JSON.stringify(stamps));
58	  } catch {
59	    /* as above — the worst case is one extra fetch */
60	  }
61	}
62	
63	/**
64	 * Throw away a cached copy we've judged unusable, clock and all.
65	 *
66	 * The clock matters as much as the payload: a stamp left behind keeps pointing
67	 * at an entry we've already rejected, so the next load makes the same bad
68	 * decision, and the next — for a day on availability, four days on the
69	 * catalogue.
70	 */
71	async function dropCached(cache, url, note) {
72	  try {
73	    await cache.delete(url);
74	  } catch (err) {
75	    note(err, url);
76	  }
77	  unstampFetch(url);
78	}
79	
80	/**
81	 * Throw away a cached copy from outside this module, for the caller that can see
82	 * something this module can't: that two separately-cached files, each valid on
83	 * its own, no longer describe the same thing. Evicting both and refetching is
84	 * how that gets repaired without making the visitor clear their storage.
85	 *
86	 * A no-op wherever Cache Storage isn't available, since there is nothing to
87	 * evict and the next read goes to the network anyway.
88	 *
89	 * @param {string} url
90	 */
91	export async function evictCached(url) {
92	  let cache = null;
93	  try {
94	    if (typeof caches !== "undefined") cache = await caches.open(CACHE_NAME);
95	  } catch {
96	    cache = null;
97	  }
98	  if (!cache) return;
99	  await dropCached(cache, url, () => {});
100	}
101	
102	/**
103	 * A cached copy we can actually use, or null.
104	 *
105	 * Every failure here is a miss, never a throw. A cached copy is an optimisation,
106	 * and the one thing it must never do is stand between the caller and the
107	 * network — but that is exactly what it did in #309: `cache.match(url)` and
108	 * `hit.json()` both ran unguarded with no fall-through, so an entry that read
109	 * back as an error propagated straight out of cachedFetchJson. The network was
110	 * never asked. With the stamp still fresh it failed the same way on every load
111	 * until the TTL expired.
112	 *
113	 * `validate` covers the quieter version of the same problem: a stored copy from
114	 * an older generation of the file, which parses cleanly and then joins to
115	 * nothing downstream. This module can't know one file's schema from another's,
116	 * so the caller that does gets to reject it.
117	 *
118	 * @returns {Promise<{data: unknown}|null>} boxed so a validly-null payload is
119	 *   distinguishable from a miss
120	 */
121	async function readCached(cache, url, validate, note) {
122	  let hit;
123	  try {
124	    hit = await cache.match(url);
125	  } catch (err) {
126	    note(err, url);
127	    return null;
128	  }
129	  if (!hit) return null;
130	
131	  let data;
132	  try {
133	    data = await hit.json();
134	  } catch (err) {
135	    note(err, url);
136	    await dropCached(cache, url, note);
137	    return null;
138	  }
139	
140	  if (validate && !validate(data)) {
141	    note(new Error(`cached copy of ${url} failed validation`), url);
